const brandGuidelinesRows = $('Reading - Brand Guidelines').all();
const winningRows = $('Reading - Winning Prompts').all() || [];
const loopItemJson = $('Loop').first().json || $node['Loop'].json;

// Extract winning prompts for Few-Shot RAG
const goodPrompts = winningRows
    .filter(row => row.json && row.json.status === 'LGTM' && row.json.design_prompt)
    .slice(-3)
    .map(row => row.json.design_prompt)
    .join('\n\n---\n\n');

const brandName = (loopItemJson.brand || loopItemJson.Brand || '').trim();
let brandPositioning = '';
let brandVoiceTone = '';
let typographyHierarchy = '';
let primaryColorPalette = '';

if (brandName && brandGuidelinesRows.length > 0) {
  const targetColumn = Object.keys(brandGuidelinesRows[0]?.json || {}).find(col => 
      col.toLowerCase().includes(brandName.toLowerCase()) && col.toLowerCase().includes('short desc')
  ) || brandName + " - Short Desc";

  for (const row of brandGuidelinesRows) {
    if (!row.json) continue;
    const rowValues = Object.values(row.json).map(v => String(v).toLowerCase());
    if (rowValues.includes('brand positioning') || rowValues.includes('brand positioning:')) {
       brandPositioning = row.json[targetColumn] || '';
    }
    if (rowValues.includes('brand voice and tone') || rowValues.includes('brand voice & tone') || rowValues.includes('brand voice and tone:')) {
       brandVoiceTone = row.json[targetColumn] || '';
    }
    if (rowValues.includes('typography hierarchy') || rowValues.includes('typography hierarchy:')) {
       typographyHierarchy = row.json[targetColumn] || '';
    }
    if (rowValues.includes('primary color palette') || rowValues.includes('primary color palette:')) {
       primaryColorPalette = row.json[targetColumn] || '';
    }
  }
}

return [{
  json: {
    ...loopItemJson,
    brand_positioning: brandPositioning,
    brand_voice_tone: brandVoiceTone,
    typography_hierarchy: typographyHierarchy,
    primary_color_palette: primaryColorPalette,
    winning_prompt_examples: goodPrompts
  }
}];

const newItems = [];
for (const item of $input.all()) {
  let outputText = item.json.output || item.json.text || '';

  outputText = outputText.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();

  let startIdx = outputText.indexOf('A stylized illustration of');
  if (startIdx === -1) startIdx = outputText.indexOf('A high quality t-shirt design graphic featuring');
  if (startIdx !== -1) {
    outputText = outputText.substring(startIdx);
  }

  outputText = outputText.replace(/^["']|["']$/g, '').trim();
  outputText = outputText.replace(/\*\*Design Prompt:\*\*\s*/i, '').trim();

  const loopItem = $('Loop').first().json;

  newItems.push({
    json: {
      month: loopItem.month || '',
      date: loopItem.date || '',
      event: loopItem.event || '',
      brand: loopItem.Brand || loopItem.brand || '',
      product: loopItem.product || 't-shirt',
      slogan: loopItem['Slogan Idea'] || loopItem.slogan || '',
      design_prompt: outputText,
      status: 'Ready for Review',
      feedback: '',
      model: 'qwen3:1.7b',
      mode: 'qwen3:1.7b'
    }
  });
}
return newItems;
